entries[198076] = { ["name"] = "Pest Fogger", ["text"] = "Binds when picked up\nUse: Throw a pest fogger that creates a poisonous explosion dealing 15 Nature damage to all enemies within 6 yards, knocking them back and reducing movement speed by 30% for 8 sec.\n\nKnock back is more effective against enemy players." }
