entries[198079] = { ["name"] = "Orders from Sarkareth", ["text"] = "Quest Item\nRequires level 20 to 70 ( 70)\n\"The Aspects are complicit in the Destroyer's crimes. Find evidence of their attempts to control us. Speak out! Resist! - Scalecommander Sarkareth\"" }
entries[198080] = { ["name"] = "Sigil of Storms", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"The illegible markings and fluctuating temperature of the sigil make this quite an interesting find.\"" }
entries[198081] = { ["name"] = "Caregiver's Charm", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 Intellect\nUse: Cast your watchful eye over your target, granting a high chance to heal them for 1847 when they receive any healing over the next 30 sec. (2 Min Cooldown)\nSell Price:" }
entries[198082] = { ["name"] = "Pre-Sentient Rock Cluster", ["text"] = "\"Only a wisp of elemental awareness remains.\"\nSell Price:" }
entries[198083] = { ["name"] = "Expedition Supply Kit", ["text"] = "Binds to Warband\nUnique\nUse: Access your Expedition Supply Kit. Use Dragon Isles Supplies to upgrade your exploration, climbing, and cataloging capabilities.\nRequires Renown Rank 6 with the Dragonscale Expedition.\n\"This kit was earned by gaining renown within the Dragonscale Expedition.\"" }
entries[198085] = { ["name"] = "Lost Obsidian Cache Key", ["text"] = "Binds when picked up\n\"The key to the Lost Obsidian Cache.\"\nSell Price:" }
entries[198086] = { ["name"] = "Darkmoon Deck: Inferno", ["text"] = "Binds when equipped\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\n+300 [Agility or Strength or Intellect]\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Use: Hurl a Smoldering Inferno at the target that deals between ( 78083 * .3)- 78083 Fire damage. Damage dealt is determined by the top-most card of the deck. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198087] = { ["name"] = "Darkmoon Deck: Rime", ["text"] = "Binds when equipped\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\n+300 [Agility or Strength or Intellect]\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Use: Deal 15897 Frost damage and apply Awakening Rime to your target for 4-12s. If the target dies while Awakening Rime is active, it explodes for 39743 Frost damage split between enemies in a 10 yard radius. Duration is determined by the top-most card of the deck. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198088] = { ["name"] = "Darkmoon Deck: Dance", ["text"] = "Binds when equipped\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\n+300 [Agility or Strength or Intellect]\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Use: Call a Refreshing Dance that bounces 6-13 times between friends and foes within 25 yards dealing 9545 Nature damage or 5200 healing. The number of bounces is determined by the top-most card of the deck. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198089] = { ["name"] = "Darkmoon Deck: Watcher", ["text"] = "Binds when equipped\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\n+300 [Agility or Strength or Intellect]\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Use: Grants the Watcher's Blessing for 5-12s and an absorb shield for 62801 damage.\nIf the shield depletes while Watcher's Blessing is active, gain 1469 versatility for the same duration. Duration is determined by the top-most card of the deck. (1 Min, 30 Sec Cooldown)\nSell Price:" }
