entries[198346] = { ["name"] = "\"Order Anything Crafters Make!\"", ["text"] = "Quest Item\n\"An Artisan's Consortium advertisement promoting that crafting orders can be made for any items, including rare and unique items only advanced crafters can make.\"" }
entries[198347] = { ["name"] = "\"Public Orders: Fast and Made For You!\"", ["text"] = "Quest Item\n\"An Artisan's Consortium advertisement promoting public crafting orders as useful for getting items crafted for you and making personal connections with crafters.\"" }
entries[198348] = { ["name"] = "\"Custom High-Quality Gear: Better Business with Personal Orders!\"", ["text"] = "Quest Item\n\"An Artisan's Consortium advertisement promoting personal and guild crafting orders which can be used to order custom-made, high-quality items with better guarantees than the public crafting order system.\"" }
