entries[198352] = { ["name"] = "Sigil of Storms", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"The illegible markings and fluctuating temperature of the sigil make this quite an interesting find.\"" }
entries[198353] = { ["name"] = "Shiverweb Egg", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[198354] = { ["name"] = "The Black Locus", ["text"] = "Quest Item\nRequires level 20 to 70 ( 70)\n\"Like mist on the night sky, the speckle of this gem demands your attention. You should keep it.\"" }
entries[198355] = { ["name"] = "Tyrhold Conduit", ["text"] = "Quest Item\nUse: Release latent magic at an elite denizen of Tyrhold, dealing damage and increasing damage taken for 20 sec. (30 Sec Cooldown)\n\"The titan relic pulses with magic.\"" }
entries[198356] = { ["name"] = "Honey Snack", ["text"] = "Use: Restores ( 45000 / 5 * 20) health and ( 60000 / 5 * 20) mana over 20 sec. Must remain seated while eating.\nSell Price:" }
entries[198357] = { ["name"] = "Rock of Aegis", ["text"] = "Binds when picked up\nOff Hand Shield\n13 Armor\nDurability 25 / 25\n\"It's unclear what the djaradin use this for, as it's far too small to protect them.\"\nSell Price:" }
entries[198387] = { ["name"] = "Excavator's Mallet", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Mace\n1 Damage Speed 2.60\n(0.4 damage per second)\nDurability 20 / 20\nRequires Renown Rank 3 with the Dragonscale Expedition.\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[198388] = { ["name"] = "Swirling Draconian Concoction", ["text"] = "Cosmetic\nBinds to Warband\nHeld In Off-hand\nRequires Renown Rank 25 with the Valdrakken Accord.\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[198389] = { ["name"] = "Weighted Potion Cylinder", ["text"] = "Cosmetic\nBinds to Warband\nHeld In Off-hand\nRequires Renown Rank 25 with the Valdrakken Accord.\nUse: Add this appearance to your Warband collection.\nSell Price:" }
