entries[198397] = { ["name"] = "Rainbow Pearl", ["text"] = "Crafting Reagent\n\"Shines with a prismatic hue.\"\nSell Price:" }
entries[198398] = { ["name"] = "Primal Proto-Whelp Scale", ["text"] = "Quest Item\n\"Incredibly tough, yet still quite flexible.\"" }
entries[198400] = { ["name"] = "Lucky Horseshoe", ["text"] = "Binds when picked up\nUnique\n\"Farrier Roscha claims this will bring you good luck on your hunts.\"\nSell Price:" }
entries[198401] = { ["name"] = "Aileron Seamoth Lure", ["text"] = "Use: Increases the chance to catch Aileron Seamoth for 30 min.\nSell Price:" }
entries[198402] = { ["name"] = "Maruuk Cooking Pot", ["text"] = "Binds when picked up\nToy\nUse: Set out a Maruuk cooking pot, allowing cooking. (5 Min Cooldown)\nRequires Renown 3 with the Maruuk Centaur and completing the quest \"Cultural Exchange\".\n\"Nomadic lifestyles demand portable cookware. The Maruuk are happy to share it with their allies.\"\nSell Price:" }
entries[198403] = { ["name"] = "Islefin Dorado Lure", ["text"] = "Use: Increases the chance to catch Islefin Dorado for 30 min.\nSell Price:" }
entries[198404] = { ["name"] = "Bottled Pheromones", ["text"] = "Binds when picked up\nUse: Open a bottle of pheromones, drawing all unoccupied, skinnable beasts and dragonkin within 60 yards to you.\n\nOnly usable outdoors in the Dragon Isles. (5 Min Cooldown)\nRequires Dragon Isles Skinning (10)\nSell Price:" }
entries[198406] = { ["name"] = "Snipped Vine", ["text"] = "Quest Item\nUnique\n\"A cutting from the lasher. Still wriggly!\"" }
entries[198407] = { ["name"] = "Azure Arcanic Amplifier", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 Intellect\nEquip: Your spells have a chance to increase your Critical Strike by 2804 for 10 sec.\nSell Price:" }
entries[198408] = { ["name"] = "Timewalker Notes", ["text"] = "Quest Item\n\"A detailed manual on how to use a timewalker staff. Someone has scribbled notes all over it.\"" }
entries[198409] = { ["name"] = "Personal Shell", ["text"] = "Binds when picked up\nToy\nUse: Enter your own Personal Shell. (1 Hour Cooldown)\n\"A place you'll always be safe in.\"" }
entries[198410] = { ["name"] = "Timewalker Staff", ["text"] = "Quest Item\n\"An instrument for manipulating time magic and shepherding the timeways.\"" }
entries[198411] = { ["name"] = "Claw of Preparedness", ["text"] = "Binds when picked up\nOne-Hand Fist Weapon\n35 - 51 Damage Speed 2.60\n(16.5 damage per second)\n+15 Agility\n+22 Stamina\n+ 16 Versatility\n+ 13 Mastery\nSell Price:" }
entries[198424] = { ["name"] = "Refine Dragon Isles Hides", ["text"] = "\"Refine rare hides and scales gathered from the creatures of the Dragon Isles to higher qualities.\"" }
entries[198425] = { ["name"] = "Refine Dragon Isles Leather", ["text"] = "\"Refine leather gathered from the creatures of the Dragon Isles to higher qualities.\"" }
entries[198426] = { ["name"] = "Refine Dragon Isles Scales", ["text"] = "\"Refine scales gathered from the creatures of the Dragon Isles to higher qualities.\"" }
entries[198428] = { ["name"] = "Tuskarr Dinghy", ["text"] = "Binds when picked up\nUnique\nToy\nUse: You can raft across water." }
entries[198429] = { ["name"] = "Typhoon Bringer", ["text"] = "Binds when picked up\nTwo-Hand Staff\n33 - 46 Damage Speed 3.60\n(11.0 damage per second)\n+130 Intellect\n+44 Stamina\n+ 30 Haste\n+ 28 Mastery\nDurability 100 / 100\n\"A small inscription reads 'Brought by Ty'foon'.\"\nSell Price:" }
entries[198430] = { ["name"] = "Time Capsule", ["text"] = "Quest Item\n\"An ancient box, left behind for those who rediscovered the Dragon Isles.\"" }
entries[198432] = { ["name"] = "Crude Wind Charm", ["text"] = "Binds when picked up\nTrinket\n+28 Intellect\nEquip: Your spells have a chance to wrap your target in winds, slicing an enemy for 64 Nature damage or granting 112 Haste to an ally over 8 sec.\nSell Price:" }
entries[198433] = { ["name"] = "zzOldDarkmoon Deckbox: Awakened Chill", ["text"] = "Binds when picked up\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Trigger (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198434] = { ["name"] = "zzOldDarkmoon Deckbox: Refreshing Dance", ["text"] = "Binds when picked up\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Trigger (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198435] = { ["name"] = "zzOldDarkmoon Deckbox: Watcher", ["text"] = "Binds when picked up\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Trigger (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198436] = { ["name"] = "Hunting Horseshoe", ["text"] = "\"Lightweight. Good for tracking prey.\"\nSell Price:" }
entries[198437] = { ["name"] = "Caravan Horseshoe", ["text"] = "\"Durable. Good for long distance travel.\"\nSell Price:" }
entries[198438] = { ["name"] = "Draconic Recipe in a Bottle", ["text"] = "Binds when picked up\n\"A crystal clear bottle with what looks to be a recipe inside. Looks useful to somebody!\"\n<Right Click to Open>" }
entries[198439] = { ["name"] = "Aged Recipe in a Bottle", ["text"] = "Binds when picked up\n\"It looks as though it's been floating around Azeroth for awhile. Now a recipe from a time long ago is here, with you.\"\n<Right Click to Open>" }
entries[198440] = { ["name"] = "Discounted Meat", ["text"] = "\"Freeze or use by yesterday.\"\nSell Price:" }
entries[198441] = { ["name"] = "Thunderspine Tenders", ["text"] = "Use: Restores ( 45000 / 5 * 20) health and ( 60000 / 5 * 20) mana over 20 sec. Must remain seated while eating.\n\"The residual electricity makes your tongue tingle.\"\nSell Price:" }
entries[198442] = { ["name"] = "Bogthwottle's Shrinky-Do", ["text"] = "Binds when picked up\nUnique (10)\nUse: Shrinks the caster and party members within 40 yards for 10 min. (3 Sec Cooldown)\n\"The scratched lettering on the label reads, 'Only the finest ingredients from, er... trust me. It's delicious!'.\"\nSell Price:" }
entries[198443] = { ["name"] = "Titan Temple Relic", ["text"] = "Quest Item\n\"A peculiar relic from the Titan Temple.\"" }
entries[198445] = { ["name"] = "Charred Zandali Chilis", ["text"] = "Quest Item\n\"Smoky and a little sweet, so long as you watch out for the seeds.\"" }
entries[198446] = { ["name"] = "Fine Suramar Vintage", ["text"] = "Quest Item\n\"Expertly selected to suit your refined dracthyr palate.\"" }
entries[198447] = { ["name"] = "Bilgewater-Imported Imitation Crab", ["text"] = "Quest Item\n\"Only the brinest will do!\"" }
entries[198448] = { ["name"] = "Dragonscale Expedition Supplies", ["text"] = "Quest Item\n\"Various supplies that belong to the Dragonscale Expedition.\"" }
entries[198449] = { ["name"] = "Pouch of Prodigious Wonders", ["text"] = "Binds to Warband\nUse: Open to gain 1250 Cosmic Flux.\nRequires Friendly reputation with The Enlightened.\n\"The Enlightened carry these pouches while wandering Zereth Mortis, believing the practice brings them closer to the First Ones.\"" }
entries[198450] = { ["name"] = "Old Crabshell", ["text"] = "Binds when picked up\n\"Discarded long ago, the shell is smooth and rounded.\"" }
entries[198451] = { ["name"] = "Lifeflame Ampoule", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 [Agility or Strength]\nUse: Unseal the ampoule and release the built-up flames of life, dealing 28339 damage split between all enemies and 42051 healing split between all allies within 10 yds. (2 Min Cooldown)\nSell Price:" }
entries[198452] = { ["name"] = "Prototype F", ["text"] = "Binds when picked up\nUnique\nDuration: 4 hrs\nUse: Equip Prototype F.\n\nUsable in the Obsidian Citadel and adjacent lava fields.\n\"One of many experimental weapons that never went beyond the prototype stage.\"\nSell Price:" }
entries[198453] = { ["name"] = "Unstable Azerite Grenade", ["text"] = "Binds when picked up\nDuration: 4 hrs\nUse: Deals 29 to 43 Arcane damage to all enemies within 7 yards of impact.\n\nUseable in the Obsdian Citadel and adjacent lava fields. (5 Sec Cooldown)\n\"Crate loads of these have been sold on the black market.\"\nSell Price:" }
entries[198454] = { ["name"] = "Draconic Treatise on Blacksmithing", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Blacksmithing Knowledge by 1.\nRequires Dragon Isles Blacksmithing (25)\n\"Contains notes on various tricks of the trade used by Blacksmiths. Can only be studied once a week.\"\nSell Price:" }
entries[198455] = { ["name"] = "Tangled Roots", ["text"] = "Binds when picked up\n\"Brown and green, tough and tender, all mixed up.\"" }
entries[198456] = { ["name"] = "Oliveye Fry", ["text"] = "Binds when picked up\n\"A young oliveye, partially transparent.\"" }
entries[198457] = { ["name"] = "Pattern: Masterwork Smock", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Exquisite Leatherworker's Smock of Panache.\nRequires Dragon Isles Leatherworking (50)\nRequires Renown 18 with the Maruuk Centaur and the Dragon Isles Leatherworking profession.\nSell Price:" }
entries[198458] = { ["name"] = "Pattern: Resplendent Cover", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Master Jeweler's Tool Holster.\nRequires Dragon Isles Leatherworking (50)\nRequires Renown Rank 18 with the Iskaara Tuskarr.\nSell Price:" }
entries[198459] = { ["name"] = "Pattern: Lavish Floral Pack", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Lavish Herbalist's Botany Pack.\nRequires Dragon Isles Leatherworking (50)\nRequires Renown Rank 18 with the Iskaara Tuskarr.\nSell Price:" }
entries[198460] = { ["name"] = "Flyspawn Beetle Parts", ["text"] = "Quest Item" }
entries[198461] = { ["name"] = "Pattern: Shockproof Gloves", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Magnificent Engineer's Pinch-Proof Handguards.\nRequires Dragon Isles Leatherworking (50)\nRequires Renown Rank 18 with the Iskaara Tuskarr.\nSell Price:" }
entries[198462] = { ["name"] = "Pattern: Flameproof Apron", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Master Blacksmith's Flame Resistant Apron.\nRequires Dragon Isles Leatherworking (50)\nRequires Renown 18 with the Maruuk Centaur and the Dragon Isles Leatherworking profession.\nSell Price:" }
entries[198463] = { ["name"] = "Pattern: Expert Alchemist's Hat", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Spectacular Alchemist's Hydrophobic Headpiece.\nRequires Dragon Isles Leatherworking (50)\nRequires Renown 18 with the Maruuk Centaur and the Dragon Isles Leatherworking profession.\nSell Price:" }
entries[198464] = { ["name"] = "Pattern: Reinforced Pack", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Superb Skinner's Tanning Rack.\nRequires Dragon Isles Leatherworking (50)\nRequires Renown 18 with the Maruuk Centaur and the Dragon Isles Leatherworking profession.\nSell Price:" }
entries[198465] = { ["name"] = "Pattern: Expert Skinner's Cap", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Resplendent Skinner's Trapping Cap.\nRequires Dragon Isles Leatherworking (50)\nRequires Renown Rank 18 with the Iskaara Tuskarr.\nSell Price:" }
entries[198474] = { ["name"] = "Artist's Easel", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Get inspired. (30 Sec Cooldown)\n\"Not everyone can become a great artist, but a great artist can come from anywhere.\"" }
entries[198475] = { ["name"] = "Broken Banding", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"A piece of a gold banding broken off a much larger statue.\"" }
entries[198476] = { ["name"] = "Painting of Introduction", ["text"] = "Quest Item\n\"Competent strokes depict the Azure Archives, shrouded in snow, as seen from a distance. There is a wistfulness about the piece.\"" }
entries[198477] = { ["name"] = "Darkmoon Deck Box: Rime", ["text"] = "Binds when picked up\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\n+244 [Agility or Strength or Intellect]\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Use: Deal 10372 Frost damage and apply Awakening Rime to your target for 4-12s. If the target dies while Awakening Rime is active, it explodes for 25929 Frost damage split between enemies in a 10 yard radius. Duration is determined by the top-most card of the deck. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198478] = { ["name"] = "Darkmoon Deck Box: Dance", ["text"] = "Binds when picked up\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\n+244 [Agility or Strength or Intellect]\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Use: Call a Refreshing Dance that bounces 6-13 times between friends and foes within 25 yards dealing 6228 Nature damage or 4133 healing. The number of bounces is determined by the top-most card of the deck. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198479] = { ["name"] = "Gale Rider", ["text"] = "Binds when picked up\nUnique\nUse: Ride the glider, reducing your falling speed for 2 min. Only usable in Kul tiras. (3 Min Cooldown)\nSell Price:" }
entries[198480] = { ["name"] = "The Resplendent Pools", ["text"] = "Quest Item\n\"A delicate palette of rose, ruby, and verdant green make up this half-finished painting of the Life Pools.\"" }
entries[198481] = { ["name"] = "Darkmoon Deck Box: Watcher", ["text"] = "Binds when picked up\nUnique-Equipped: Darkmoon Deck (1)\nTrinket\n+244 [Agility or Strength or Intellect]\nEquip: Equip: Periodically shuffle the deck while in combat.\nUse: Use: Grants the Watcher's Blessing for 5-12s and an absorb shield for 51162 damage.\nIf the shield depletes while Watcher's Blessing is active, gain 1230 versatility for the same duration. Duration is determined by the top-most card of the deck. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[198482] = { ["name"] = "The Spiral of the Kurgans", ["text"] = "Quest Item\n\"Spiral patterns curve around gentle, green hills as white, billowing winds blow trees sideways in this painting of the Ohn'ahran Plains.\"" }
entries[198484] = { ["name"] = "Brackenhide's Decay", ["text"] = "Quest Item\n\"A heavy green fog hangs over a rotting forest in this painting. The canvas itself smells foul.\"" }
entries[198485] = { ["name"] = "Abandoned Scroll", ["text"] = "Unique\n\"Written in Draconic. Someone must have dropped this.\"\n<Right Click to Read>\nSell Price:" }
entries[198486] = { ["name"] = "Windscale Rider", ["text"] = "Binds when picked up\nUnique\nUse: Ride the glider, reducing your falling speed for 2 min. Only usable in the Dragon Isles. (3 Min Cooldown)\nSell Price:" }
entries[198487] = { ["name"] = "Iridescent Water", ["text"] = "Crafting Reagent\n\"A light and bubbly liquid frequently used by Scribes. Can be purchased from vendors.\"\nSell Price:" }
entries[198488] = { ["name"] = "Staff of Discovery", ["text"] = "Binds when picked up\nTwo-Hand Staff\n33 - 46 Damage Speed 3.60\n(11.0 damage per second)\n+130 Intellect\n+44 Stamina\n+ 28 Critical Strike\n+ 30 Versatility\nDurability 85 / 85\nSell Price:" }
entries[198489] = { ["name"] = "Dreamscape Prism", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 Intellect\nEquip: Your healing spells have a chance to put you into a waking dream, granting additional mana regeneration and increasing your Mastery by 1402 for 20 sec.\nSell Price:" }
entries[198490] = { ["name"] = "Bushwhacker's Compass", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 [Agility or Strength]\nEquip: Your attacks have a chance for the compass to show you a direction, increasing your Critical Strike, Haste, Mastery, or Versatility by 2043 for 12 sec.\n\"Veteran explorers know that a compass is the best way to get out of (and in to) trouble.\"\nSell Price:" }
entries[198510] = { ["name"] = "Draconic Treatise on Engineering", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Engineering Knowledge by 1.\nRequires Dragon Isles Engineering (25)\n\"Contains notes on various tricks of the trade used by Engineers. Can only be studied once a week.\"\nSell Price:" }
entries[198511] = { ["name"] = "Building Materials", ["text"] = "Quest Item\n\"The crumbled remains of an earth elemental, calling it building materials is very charitable.\"" }
entries[198512] = { ["name"] = "The Great Halls", ["text"] = "Quest Item\n\"Barely more than a sketch, tall pillars and bright lights decorate this half-finished painting of the Halls of Infusion.\"" }
entries[198513] = { ["name"] = "The Academy", ["text"] = "Quest Item\n\"Colorful dragonflight banners hang over a massive wall as drakonids play below in this painting of Algeth'ar Academy.\"" }
entries[198514] = { ["name"] = "The Sealed Vault", ["text"] = "Quest Item\n\"Great splatters of purple and blue denote bursts of arcane magic in this painting of the Azure Vault.\"" }
entries[198515] = { ["name"] = "The Fire Labs", ["text"] = "Quest Item\n\"This painting of Neltharus is barely more than vague smudges of red, orange, and black.\"" }
entries[198516] = { ["name"] = "Hudson's Final Drawing", ["text"] = "Quest Item\n\"An unfinished sketch of Hudson and Ranpiata, their heads close together, smiling.\"" }
entries[198517] = { ["name"] = "Pelt of Konkhular", ["text"] = "Quest Item\n\"The color of this pelt blends well with the rocks and dirt in the area.\"" }
