entries[198529] = { ["name"] = "Wayfarer's Iron Torch", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 [Agility or Strength]\nEquip: When you take damage, the torch has a chance to bathe you in light, healing you for 22705 . The torchlight's healing increases based on your missing health.\nSell Price:" }
entries[198530] = { ["name"] = "Raw Zandali Chilis", ["text"] = "Quest Item\nUse: Throw into a cooking fire in the Dragonscale Basecamp to make Charred Zandali Chilis. (3 Sec Cooldown)\nRequires level 10 to 70 ( 70)\n\"Tough and unpleasantly acrid, without being cooked.\"" }
entries[198532] = { ["name"] = "The Cartographer's Calipers", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 Intellect\nEquip: Your spells have a chance to deal 7802 damage or 11717 healing to a target with the lowest health within 10 yds, based on the spell you cast.\n\"What separates a master cartographer from the rest is one thing: precision.\"\nSell Price:" }
entries[198533] = { ["name"] = "Recipe: Aerated Phial of Quick Hands", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Aerated Phials of Quick Hands.\nRequires Dragon Isles Alchemy (10)\nRequires Respected reputation with the Artisan's Consortium.\nSell Price:" }
entries[198537] = { ["name"] = "Taivan's Trumpet", ["text"] = "Binds when picked up\nToy\nUse: Summon Taivan to your side. Taivan increases the Versatility of those nearby by 1 . (5 Min Cooldown)\n\"Taivan loves the sound of this trumpet made of argali horn.\"" }
entries[198538] = { ["name"] = "Magically Bound Message", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"The mysterious parchment emanates a mesmerizing purple colored dust slowly outward, where it dissipates after a fleeting moment.\"" }
entries[198539] = { ["name"] = "Breath of the Plains", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+382 Intellect\nEquip: Your spells have a chance to increase your Haste by 1518 and movement speed by 5% for 20 sec.\nSell Price:" }
