entries[198825] = { ["name"] = "Zenet Hatchling", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The hardest winds begin with a gust and a flap.\"\nDrop:\nZenet Egg\nZone:\nOhn'ahran Plains" }
entries[198827] = { ["name"] = "Magical Snow Sled", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Jump on and sled! (5 Min Cooldown)\nRequires Renown Rank 26 with the Iskaara Tuskarr.\nRequires Renown Rank 27 with the Iskaara Tuskarr.\n\"Get on!!\"" }
entries[198830] = { ["name"] = "Conjured Tasty Hatchling's Treat", ["text"] = "Conjured Item\nUnique: Conjured Dessert (1)\nUse: Lure a friendly whelpling out of hiding with an uncomfortably squishy but nonetheless appealing treat." }
entries[198831] = { ["name"] = "Conjured Snow in a Cone", ["text"] = "Conjured Item\nUnique: Conjured Dessert (1)\nUse: Yum!" }
entries[198832] = { ["name"] = "Conjured Blubbery Muffin", ["text"] = "Conjured Item\nUnique: Conjured Dessert (1)\nUse: Yum...?" }
entries[198833] = { ["name"] = "Conjured Celebratory Cake", ["text"] = "Unique: Conjured Dessert (1)\nUse: Set out a delightful cake to celebrate a momentous occasion! (2 Min Cooldown)" }
entries[198834] = { ["name"] = "Scribbled Bark Chunks", ["text"] = "Quest Item\nUnique\n\"Bark-like scroll pieces stolen from the Winterpelt Furbolg.\"" }
entries[198836] = { ["name"] = "Arclight Vital Correctors", ["text"] = "Binds when picked up\nUse: Carelessly cross a few frayed wires within the vicinity of a fallen ally in a desperate attempt to jolt them back to life with 60% health and 20% mana. Castable in combat. What could possibly go wrong?\n\nCannot be used by players higher than level 70. (10 Min Cooldown)\nRequires Dragon Isles Engineering (1)\n\"One way or another, someone's getting zapped.\"\nSell Price:" }
entries[198837] = { ["name"] = "Curious Hide Scraps", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Skinning Knowledge by 1.\nRequires Dragon Isles Skinning (25)" }
entries[198839] = { ["name"] = "Design: Signet of Titanic Insight", ["text"] = "Use: Teaches you how to craft Signet of Titanic Insight.\nRequires Dragon Isles Jewelcrafting (1)\nSell Price:" }
entries[198840] = { ["name"] = "Kalecite Cluster", ["text"] = "\"New and experienced lapidaries alike often mistake this fragile gemstone with the far more valuable Malygite. You, on the other hand, cannot be fooled!\"\nSell Price:" }
entries[198841] = { ["name"] = "Large Sample of Curious Hide", ["text"] = "Binds when picked up\nUse: Study to increase your Dragon Isles Skinning Knowledge by 2.\nRequires Dragon Isles Skinning (25)\n\"You suspect it will be a while before you find such a wondrous sample of curious hide again.\"" }
entries[198842] = { ["name"] = "Tallstrider Feather", ["text"] = "Quest Item\n\"WIP DESCRIPTION\"" }
entries[198843] = { ["name"] = "Emerald Gardens Explorer's Notes", ["text"] = "Binds when picked up\nUse: Marks your map with the location of a treasure in the Ohn'ahran Plains.\n\"I saw a glint of green passing by one of the caves in the Emerald Gardens. It could be a precious gem! Or just another sleeping dragon...\"" }
entries[198847] = { ["name"] = "Flyspawn Chitin", ["text"] = "Quest Item\n\"All the crunch a young duckling needs.\"" }
entries[198848] = { ["name"] = "Flyspawn Thorax", ["text"] = "Quest Item\n\"Why is it dripping still?\"" }
entries[198852] = { ["name"] = "Bear Termination Orders", ["text"] = "Binds when picked up\nUse: Marks your map with the location of a treasure in Thaldraszus.\n\"The amber gems we were searching for were spotted in a cave. Unfortunately, that cave appears to be the den of a rather unfriendly bear. Take it out, and we can finally get to those gems.\"" }
entries[198854] = { ["name"] = "Archeologist Artifact Notes", ["text"] = "Binds when picked up\nUnique\nUse: Marks your map with the location of a treasure in The Waking Shores.\n\"Detailed research findings that indicate a possible treasure location near the Wingrest Embassy.\"" }
entries[198855] = { ["name"] = "Throw Net", ["text"] = "Quest Item\nUse: Throw at Stock Fish within 15 yards. (5 Sec Cooldown)\n\"This net can be used to catch plenty of fish and replenish the fishing hole.\"" }
entries[198856] = { ["name"] = "Flyspawn Mandibles", ["text"] = "Quest Item\n\"Some say this is the best part.\"" }
entries[198857] = { ["name"] = "Lucky Duck", ["text"] = "Binds when picked up\nToy\nUse: Escort Lucky Duck for a short time. You don't want to disappoint Lillistraza, do you? (30 Min Cooldown)\nSell Price:" }
entries[198858] = { ["name"] = "Energized Arcana Vessel", ["text"] = "Quest Item\nUnique\n\"The enchanted aura surrounding the vessel appears to be waning.\"" }
entries[198859] = { ["name"] = "Revealing Dragon's Eye", ["text"] = "Quest Item\nUnique\nUse: Empowers the wearer to see disguised Primalists within 30 yards within Valdrakken." }
