entries[198870] = { ["name"] = "Otto", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Relax. The future will unfold as it was meant to, one way or an otter.\"\nQuest:\nThe Way to an Otto's Heart" }
entries[198871] = { ["name"] = "Iskaara Trader's Ottuk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"There are no guarantees when you purchase an ottuk from Tattukiaka. At least they're cute.\"\nVendor:\nTattukiaka\nZone:\nThe Azure Span\nCost:\n1\n1" }
entries[198872] = { ["name"] = "Brown Scouting Ottuk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 25 with the Iskaara Tuskarr.\n\n\"Wily and playful in their natural habitat, ottuks possess keen eyes that can scout far afield as ably as they watch for predators.\"\nFaction:\nIskaara Tuskarr\nRenown:\n25\nVendor:\nTatto\nLocation:\nIskaara\nCost:\n2\n2\n750" }
entries[198873] = { ["name"] = "Ivory Trader's Ottuk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"No adult knows why some ottuks are white, but any tuskarr child can tell you: it's because they eat too much snow.\"\nVendor:\nTattukiaka\nZone:\nThe Azure Span\nCost:\n1\n1\n1" }
