entries[199061] = { ["name"] = "A Guide to Rare Fish", ["text"] = "Binds when picked up\nUse: Marks your map with the location of a treasure in The Waking Shores.\n\"The Bubble Drifter is a particularly timid fish, but is attracted to certain pecular scents.\"" }
entries[199062] = { ["name"] = "Ruby Gem Cluster Map", ["text"] = "Binds when picked up\nUse: Marks your map with the location of a treasure in The Waking Shores.\n\"Long ago, clusters of ruby gems would grow within the Ruby Life Pools and surrounding areas. See if you can find one such cluster.\"" }
entries[199063] = { ["name"] = "Salted Fish Scraps", ["text"] = "Tuskarr Feast Reagent\nBinds when picked up\nUnique\nUse: Throw them into the pot!\n\"Heavily-salted bits of fish.\"\nSell Price:" }
entries[199064] = { ["name"] = "Vitrified Sand", ["text"] = "Quest Item\n\"Some of the golden dust has melted, forming a brittle lattice that shimmers faintly when broken.\"" }
entries[199065] = { ["name"] = "Sorrowful Letter", ["text"] = "Binds when picked up\nUse: Marks your map with the location of a treasure in The Azure Span.\n\"Well, my proposal failed... The jewel lies at the bottom of a crystal waterfall where I threw it if you want it back.- Dongi\"" }
entries[199066] = { ["name"] = "Letter of Caution", ["text"] = "Binds when picked up\nUse: Marks your map with the location of a treasure in The Azure Span.\n\"A letter of warning seemingly written by Gnolls to warn against an aggressive enemy.\"" }
entries[199067] = { ["name"] = "Precious Plans", ["text"] = "Binds when picked up\nUse: Marks your map with the location of a treasure in The Azure Span.\n\"The precious sapphires within the Dragon Isles are very rare and can be difficult to obtain. The best place to look would be the snowy regions, although I have to warn you, there are many monstrous creatures in those areas.\"" }
